          // 每回合结束：雪人生成蜜果 + 碎冰\n 9908        if (steps.length) drainPendingSubHits(steps[steps.length - 1]);\n 9909        if (events.length && steps.length) { steps[steps.length - 1].events.push(...events); events = []; steps[steps.length - 1].snap = snapshot(); ste…\n 9910        checkWin();"}],"impl":"impl"},"attr:PHYSIC_DEFENCE":{"label":"物理防御（PHYSIC_DEFENCE）","cat":"attr","doc":"属性由 attr() 汇总：基础值、MODIFY_ATTRIBUTE / CONVERT_ATTRIBUTE / 光环（同类取最高）与条件型修正逐项累加。","anchors":[{"f":"battle-sim-core.js","l":2437,"sym":"U","role":"读取属性","code":" 2436                hp: u.hp, hp_max: maxHpOf(u), physic_attack: attr(u, 'PHYSIC_ATTACK'),\n 2437                spell_attack: attr(u, 'SPELL_ATTACK'), physic_defence: attr(u, 'PHYSIC_DEFENCE'),\n 2438                spell_defence: attr(u, 'SPELL_DEFENCE'), speed: attr(u, 'SPEED'),\n 2439                damage: attr(u, 'DAMAGE'),\n 2440                crit_ratio: K.CritBaseChance + attr(u, 'CRIT_RATIO'),"},{"f":"battle-sim-core.js","l":2010,"sym":"attr","role":"属性汇总 attr()：基础值 + 常驻/状态/光环修正","code":" 2010      function attr(u, A, ctx) {\n 2011        if (STORE_ATTRS.has(A)) return attrRaw(u, A, ctx || null) + (u?.store?.[A] || 0);\n 2012        if (!ctx) {\n 2013          if (cacheEpoch !== sim.epoch) { staticCache.clear(); cacheEpoch = sim.epoch; }\n 2014          const ck = u.uid + '|' + A;\n 2015          if (staticCache.has(ck)) return staticCache.get(ck);\n 2016          const v = attrRaw(u, A, null);"}],"impl":"impl"},"lua:getBuffCountBySubType":{"label":"Lua：getBuffCountBySubType","cat":"lua","doc":"客户端 Lua 条件/动态参数里调用的 API，由引擎内置解释器提供同名实现。","anchors":[{"f":"battle-sim-core.js","l":2507,"sym":"U","role":"Lua API 实现","code":" 2507            getBuffCountBySubType: (t, n = 1) => buffCount(u, b => b.def.sb === t) >= (n || 1),\n 2508            hasBuffEffect: (e) => u.buffs.some(b => effectBit(b.def.et) === e),\n 2509            isAbnormalState: (a) => u.buffs.some(b => b.def.et && String(M.enums.abnormal?.[a] || '') === b.def.et),\n 2510            isEnemy: (o) => !!o && !!o.__unit && o.__unit.side !== u.side,\n 2511            isFriend: (o) => !!o && !!o.__unit && o.__unit.side === u.side,"}],"impl":"impl"},"id:14673":{"label":"#14673 专属处理","cat":"id","doc":"引擎为该技能/特技/状态编写的专属逻辑或修正说明。","anchors":[{"f":"battle-sim-core.js","l":4718,"sym":"EFFECTS.BUFF","role":"专属处理（引擎按 id 识别）","code":" 4716          }\n 4717          // Client self-cast correction: some BUFF rows are configured with one\n 4718          // turn LESS and annotated 「自施法补正」 in speciality.name (#14673,\n 4719          // 流星队 后备隐藏脂肪; skill 11907 says 「持续2回合」 but p[1] = 1).\n 4720          const selfBonus = /自施法补正/.test(s.n || '') ? 1 : 0;\n 4721          for (const t of targetsOf(inst, ctx)) for (const id of ids) {\n 4722            const turns = (s.p[1] || 0) + (t === inst.owner ? selfBonus : 0);"}],"impl":"impl"},"id:14680":{"label":"#14680 专属处理","cat":"id","doc":"引擎为该技能/特技/状态编写的专属逻辑或修正说明。","anchors":[{"f":"battle-sim-core.js","l":6418,"sym":"simulate","role":"专属处理（引擎按 id 识别）","code":" 6416      //   • SKILL_RANGE specialities on the unit (passives + buffs), each scaled\n 6417      //     by its buff STACKS (#12417 后备隐藏脂肪 +1/层,\n 6418      //     #14680/#14681 七手八脚的分工合作 +1, #14726 不屈不挠 +2),\n 6419      //   • EXTEND_CAST_RANGE specialities (client extend_cast_range_buffs),\n 6420      //   • SKILL_RANGE specialities declared on the SKILL itself.\n 6421      // The same rows feed the AI (rangeMods) and the visible character state\n 6422      // (skillStateOf), so they can never disagree."}],"impl":"impl"},"id:14681":{"label":"#14681 专属处理","cat":"id","doc":"引擎为该技能/特技/状态编写的专属逻辑或修正说明。","anchors":[{"f":"battle-sim-core.js","l":6418,"sym":"simulate","role":"专属处理（引擎按 id 识别）","code":" 6416      //   • SKILL_RANGE specialities on the unit (passives + buffs), each scaled\n 6417      //     by its buff STACKS (#12417 后备隐藏脂肪 +1/层,\n 6418      //     #14680/#14681 七手八脚的分工合作 +1, #14726 不屈不挠 +2),\n 6419      //   • EXTEND_CAST_RANGE specialities (client extend_cast_range_buffs),\n 6420      //   • SKILL_RANGE specialities declared on the SKILL itself.\n 6421      // The same rows feed the AI (rangeMods) and the visible character state\n 6422      // (skillStateOf), so they can never disagree."}],"impl":"impl"},"lua:isCounterDefence":{"label":"Lua：isCounterDefence","cat":"lua","doc":"客户端 Lua 条件/动态参数里调用的 API，由引擎内置解释器提供同名实现。","anchors":[{"f":"battle-sim-core.js","l":3198,"sym":"luaEnv","role":"Lua API 实现","code":" 3198          isCounterDefence: (s, o) => !!(s?.__skill && o?.__unit && s.__caster !== o.__unit && s.__flags.counter &&\n 3199            (s.__flags.targets || []).includes(o.__unit)),\n 3200        };\n 3201        const battle = {AITemplate: {AI_ROLER_STATE: {War: 1, Peace: 0},\n 3202          NONE: 0, MELEE: 1, RANGED: 2, SUPPORT: 3, WAR: 1, PEACE: 0}};"}],"impl":"impl"},"type:CHANGE_PROFESSION_BY_BUFF":{"label":"改变职业(Buff)（CHANGE_PROFESSION_BY_BUFF）","cat":"type","doc":"","anchors":[{"f":"battle-sim-core.js","l":5794,"sym":"EFFECTS.CHANGE_PROFESSION_BY_BUFF","role":"声明型占位（由下方读取点生效）","code":" 5793        },\n 5794        CHANGE_PROFESSION_BY_BUFF(inst) { /* declarative: read by profOf() */ },\n 5795        CANT_ASSIST(inst, ctx) { /* declarative: read by the 援护防御 guard search and assist-attack queue */ },\n 5796        CANT_TRANSFER(inst, ctx) { markAction(inst, ctx, 'transferImmuneAction'); },\n 5797        CANT_REBORN(inst, ctx) { /* declarative: read by dealDamage() before 不屈 */ },\n 5798        CONVERT_SKILL(inst) { if (inst.owner) inst.owner.flags.convertSkill = inst.spec.p[0] || 1; },\n 5799        CANT_COUNTER(inst, ctx) { /* declarative: read by queueCounter() */ },"},{"f":"battle-sim-core.js","l":3545,"sym":"profOf","role":"声明的读取函数","code":" 3545      function profOf(u) {\n 3546        if (!u) return 0;\n 3547        const o = u.profOverride;\n 3548        if (o && sim.round <= o.until) return o.prof;\n 3549        if (!u.base || !hasSpecTypeNow(u, 'CHANGE_PROFESSION_BY_BUFF')) return u.prof;\n 3550        const inst = unitSpecs(u).find(i => i.spec.t === 'CHANGE_PROFESSION_BY_BUFF' && cond(i, {target: u}, true));\n 3551        return inst ? (Number(inst.spec.p[0]) || u.prof) : u.prof;\n 3552      }\n 3553      // 「技能射程高度变动」SKILL_HEIGHT p = [最小高度, 最大高度]: widens the"},{"f":"battle-sim-core.js","l":3549,"sym":"profOf","role":"读取/派发点","code":" 3548        if (o && sim.round <= o.until) return o.prof;\n 3549        if (!u.base || !hasSpecTypeNow(u, 'CHANGE_PROFESSION_BY_BUFF')) return u.prof;\n 3550        const inst = unitSpecs(u).find(i => i.spec.t === 'CHANGE_PROFESSION_BY_BUFF' && cond(i, {target: u}, true));\n 3551        return inst ? (Number(inst.spec.p[0]) || u.prof) : u.prof;\n 3552      }\n 3553      // 「技能射程高度变动」SKILL_HEIGHT p = [最小高度, 最大高度]: widens the\n 3554      // height window of the caster's cast range (珀列维特「职业技能高低差+4/6/8」,"}],"client":{"speciality_type":129,"params":["职业大类","职业种类","",""],"sparam":""},"impl":"decl"},"sj:find_empty":{"label":"复合参数 sparam.find_empty","cat":"sj","doc":"客户端特技的 JSON 复合参数，导出为 spec.sj，由对应处理器读取。","anchors":[{"f":"battle-sim-core.js","l":4976,"sym":"EFFECTS.PLACE_TRAP","role":"复合参数读取","code":" 4975            const made = placeObject(owner, 'PLACE_TRAP', inst.spec.p[0], inst.spec, sub);\n 4976            if (made && o && /find_empty|place_on_unit|near_caster/.test(sp)) made.side = o.side;\n 4977          }\n 4978        },\n 4979        REMOVE_PROPS(inst, ctx) {\n 4980          const o = ctx.object || ctx.prop || objectAt(ctx.target?.x, ctx.target?.y);"}],"impl":"impl"},"id:1984":{"label":"#1984 专属处理","cat":"id","doc":"引擎为该技能/特技/状态编写的专属逻辑或修正说明。","anchors":[{"f":"battle-sim-core.js","l":790,"sym":"utilitySide","role":"专属处理（引擎按 id 识别）","code":"  788        'TACTICS_SKILL_GROUP', 'MAKE_OTHER_CAST_SKILL', 'CAST_SKILL', 'PLACE_ITEM', 'PLACE_TRAP',\n  789        // An AOE speciality's own target_type says which side the skill hits.\n  790        // 麦莎·SP「全装甲集火号令！」only carries AOE #1984 (tt=2 敌方);\n  791        // without this it was classified as a friendly-only buff and fired at\n  792        // empty/friendly tiles with zero damage.\n  793        'AOE']);\n  794      for (const sid of s.sp || []) {"},{"f":"battle-sim-core.js","l":6758,"sym":"affects","role":"专属处理（引擎按 id 识别）","code":" 6756          return u.side === caster.side;\n 6757        // Status-class 「号令」skills declare their enemy side through the AOE\n 6758        // speciality's own target_type=2 (全装甲集火号令！→ AOE #1984 tt=2),\n 6759        // NOT through skill.target_type (a 3 there means 自身范围内, used by\n 6760        // 迎风持盾 / 灵光一闪的傲人智慧 which buff FRIENDLIES).\n 6761        if (aoeEnemy) return u.side !== caster.side;\n 6762        if (isUtility(s)) {"}],"impl":"impl"},"lua:CombatDistace":{"label":"Lua：CombatDistace","cat":"lua","doc":"客户端 Lua 条件/动态参数里调用的 API，由引擎内置解释器提供同名实现。","anchors":[{"f":"battle-sim-core.js","l":3174,"sym":"luaEnv","role":"Lua API 实现","code":" 3174          CombatDistace: () => (c.attacker && c.defender ? manhattan(c.attacker, c.defender) : 0),\n 3175          CasterLocation: (a, b, list) => {\n 3176            // Two client forms: (0,1) means \"any location\" and (a,b,terrains)\n 3177            // tests the caster's terrain type.\n 3178            if (!Array.isArray(list)) return true;"}],"impl":"impl"},"id:9499":{"label":"#9499 专属处理","cat":"id","doc":"引擎为该技能/特技/状态编写的专属逻辑或修正说明。","anchors":[{"f":"battle-sim-core.js","l":7716,"sym":"alertState","role":"专属处理（引擎按 id 识别）","code":" 7714          const strengthened = list.some(i => i.spec.t === 'STRENGTHEN_ALERT');\n 7715          // STRENGTHEN_ALERT comes in two client rows: #9472「警戒强化」(安娜,\n 7716          // 只提升警戒且无法被打断) and #9499「强制警戒（可打断技能）」. Only the\n 7717          // latter — or an explicit FORCE_STOP speciality on the alert skill —\n 7718          // stops the mover. Equating every 强制警戒 with FORCE_STOP made 安娜's\n 7719          // alert interrupt every action, which the client never does.\n 7720          const interrupts = list.some(i => i.spec.t === 'STRENGTHEN_ALERT' &&"}],"impl":"impl"},"lua:GetSourceEntity":{"label":"Lua：GetSourceEntity","cat":"lua","doc":"客户端 Lua 条件/动态参数里调用的 API，由引擎内置解释器提供同名实现。","anchors":[{"f":"battle-sim-core.js","l":2648,"sym":"B","role":"Lua API 实现","code":" 2648        GetSourceEntity: () => U(b.src),\n 2649        // A buff the client shows in the status bar (buff.ui / show_in_ui).\n 2650        IsShowUI: () => b.def.ui !== false && !b.aura,\n 2651        getSpecialityByID: (id) => (b.def.sp || []).some(x => Number(x) === Number(id))\n 2652          ? specRec(Number(id)) : null}};"}],"impl":"impl"},"at:14":{"label":"被格挡（发动）（active_time 14）","cat":"at","doc":"客户端 active_time 时点：特技只在该时点被派发，fire() 收集持有者全部特技（含状态带来的特技），按 sparam.priority 与声明顺序依次结算。","anchors":[{"f":"battle-sim-core.js","l":7344,"sym":"castSkill","role":"派发 fire(14)","code":" 7343              : unitSpecs(t).find(i => i.spec.t === 'PARRY' && limitOk(i) && cond(i, ctx));\n 7344            if (parry) { spend(parry); bump(cov.executed, 'PARRY'); fire(13, t, at({defender: t, target: caster})); fire(14, caster, ctx); }\n 7345          }\n 7346          if (!t.alive) continue;\n 7347          const selfCast = t === caster && s.dt !== 3;"}],"impl":"impl"},"lua:IgnoreKnockbackOrUnMovable":{"label":"Lua：IgnoreKnockbackOrUnMovable","cat":"lua","doc":"客户端 Lua 条件/动态参数里调用的 API，由引擎内置解释器提供同名实现。","anchors":[{"f":"battle-sim-core.js","l":2583,"sym":"U","role":"Lua API 实现","code":" 2583            IgnoreKnockbackOrUnMovable: () => immuneToKnockback(u) || hasEffect(u, 'Immobilize'),\n 2584            // `map:getNeighborPropsCount` is the map form; the unit form is the\n 2585            // same query centred on this unit.\n 2586            getNeighborPropsCount: (friend, lo, hi, attackable) => neighborProps(u, friend, lo, hi, attackable),\n 2587            // Did this unit change any terrain tile during the current round?"}],"impl":"impl"},"id:14726":{"label":"#14726 专属处理","cat":"id","doc":"引擎为该技能/特技/状态编写的专属逻辑或修正说明。","anchors":[{"f":"battle-sim-core.js","l":6418,"sym":"simulate","role":"专属处理（引擎按 id 识别）","code":" 6416      //   • SKILL_RANGE specialities on the unit (passives + buffs), each scaled\n 6417      //     by its buff STACKS (#12417 后备隐藏脂肪 +1/层,\n 6418      //     #14680/#14681 七手八脚的分工合作 +1, #14726 不屈不挠 +2),\n 6419      //   • EXTEND_CAST_RANGE specialities (client extend_cast_range_buffs),\n 6420      //   • SKILL_RANGE specialities declared on the SKILL itself.\n 6421      // The same rows feed the AI (rangeMods) and the visible character state\n 6422      // (skillStateOf), so they can never disagree."}],"impl":"impl"},"type:BUFF_DURATION":{"label":"BUFF持续时间（BUFF_DURATION）","cat":"type","doc":"","anchors":[{"f":"battle-sim-core.js","l":5081,"sym":"EFFECTS.BUFF_DURATION","role":"效果处理器 EFFECTS.BUFF_DURATION","code":" 5080        },\n 5081        BUFF_DURATION(inst, ctx) {\n 5082          const b = inst.buff;\n 5083          if (b && Number.isFinite(b.turns)) b.turns += inst.spec.p[0] || 0;\n 5084        },\n 5085        AFFILIATE_BUFF(inst, ctx) {\n 5086          // Link a second buff to the owner of the current one."}],"client":{"speciality_type":93,"params":["大类列表","效果类列表","BUFF ID","持续时间"],"sparam":"复合"},"impl":"impl"},"lua:GetAttributeModify":{"label":"Lua：GetAttributeModify","cat":"lua","doc":"客户端 Lua 条件/动态参数里调用的 API，由引擎内置解释器提供同名实现。","anchors":[{"f":"battle-sim-core.js","l":2577,"sym":"U","role":"Lua API 实现","code":" 2577            GetAttributeModify: (id) => {\n 2578              const n = attrName(id);\n 2579              return n ? Math.round(attr(u, n) - (u.base?.[n] || 0)) : 0;\n 2580            },\n 2581            isState: (at) => !!sim.live.get(u)?.has(at),"}],"impl":"impl"},"type:MODIFY_WT":{"label":"等待时间（MODIFY_WT）","cat":"type","doc":"Client effect types that only appear outside the current cup closure but are declared in speciality_type.json. Keep them recognised so a future data refresh does not silently drop them.","anchors":[{"f":"battle-sim-core.js","l":5824,"sym":"EFFECTS.MODIFY_WT","role":"效果处理器 EFFECTS.MODIFY_WT","code":" 5823        // future data refresh does not silently drop them.\n 5824        MODIFY_WT(inst) { if (inst.owner) inst.owner.flags.modifyWt = inst.spec.p[0] || 0; },\n 5825        ROGUE_MONEY_MODIFY(inst) { if (inst.owner) inst.owner.flags.rogueMoney = inst.spec.p[0] || 0; },\n 5826        ROGUE_TEAM_HP_MODIFY(inst) {\n 5827          const v = inst.spec.p[0] || 0;\n 5828          for (const u of units) if (u.alive && u.side === inst.owner.side) u.hp = Math.min(maxHpOf(u), u.hp + v);\n 5829        },"}],"client":{"speciality_type":10,"params":["数值","百分比","",""],"sparam":""},"impl":"impl"},"id:15386":{"label":"#15386 专属处理","cat":"id","doc":"引擎为该技能/特技/状态编写的专属逻辑或修正说明。","anchors":[{"f":"battle-sim-core.js","l":3862,"sym":"runSkillSpecs","role":"专属处理（引擎按 id 识别）","code":" 3860          const inst = {spec, sid, owner: caster, src: 'skill:' + skill.id, name: skill.n, skill};\n 3861          // A head-skill AOE marker must hit EVERY enemy in the skill's OWN\n 3862          // (narrower) AOE, not just `primary`: 审判诸罪之光 #15386 declares\n 3863          // AOE 257 (1*6 middle column) + BUFF 5100, while DISPLAY_AOE widens\n 3864          // the damage footprint to AOE 256 (3*6). The middle-column marker is\n 3865          // what makes the follow-up's conditional +30% (70% → 100%) fire.\n 3866          if (aoeUnits?.length && at === 2 && Number(spec.tt) === 2 &&"},{"f":"battle-sim-core.js","l":6556,"sym":"simulate","role":"专属处理（引擎按 id 识别）","code":" 6554      // Client speciality type 233 「AI判定用的AOE范围(配在主技能)」:\n 6555      // 「替代原来技能的AOE范围，同时会屏蔽后续技能的范围(只对AI生效)」.\n 6556      // 审判诸罪之光 #15386 declares head AOE 257 (1*6, the middle column that\n 6557      // gets the 加伤标记) but DISPLAY_AOE #27305 → AOE 256 (3*6, the real\n 6558      // sweep); its idskill_follow #15382 owns the 70% damage. Both the AI and\n 6559      // the cast must use the 3*6 UNION, and the follow-up's own AOE is masked\n 6560      // so the blast is not counted twice. Previously DISPLAY_AOE was a no-op,"},{"f":"battle-sim-core.js","l":6580,"sym":"targetCells","role":"专属处理（引擎按 id 识别）","code":" 6578        const out = [];\n 6579        if (s.aim === 'direction') {\n 6580          // A direction skill with range_min/max = 0 (审判诸罪之光 #15386)\n 6581          // targets a DIRECTION, not a block. Enumerate ALL four sweeps from\n 6582          // the caster's own tile, each carrying `dir` for areaCells(). The\n 6583          // old early return collapsed these to one origin cell with no dir,\n 6584          // so areaCells() always fell back to \"east\" and the AI never found"}],"impl":"impl"},"type:BUFF_MODIFY_ATTRIBUTE":{"label":"状态属性修正（BUFF_MODIFY_ATTRIBUTE）","cat":"type","doc":"","anchors":[{"f":"battle-sim-core.js","l":5806,"sym":"EFFECTS.BUFF_MODIFY_ATTRIBUTE","role":"声明型占位（由下方读取点生效）","code":" 5805        DEEP_HYPNOTIZE(inst, ctx) { for (const t of targetsOf(inst, ctx)) if (t.alive) t.flags.deepSleep = true; },\n 5806        BUFF_MODIFY_ATTRIBUTE(inst) { /* declarative: summed by attr() via buffTypeCountValue() */ },\n 5807        FADE(inst) { if (inst.owner) inst.owner.flags.fade = true; },\n 5808        IGNORE_PROFESSION_RESTRAIN(inst) { /* declarative: read by restrainSpecs() */ },\n 5809        // NOT_TURN_AROUND is declared once at the top of EFFECTS; the duplicate\n 5810        // flag-only copy was removed (same JS-object-literal shadowing bug).\n 5811        DISPLAY_AOE(inst) { /* client UI hint only */ },"},{"f":"battle-sim-core.js","l":2010,"sym":"attr","role":"声明的读取函数","code":" 2010      function attr(u, A, ctx) {\n 2011        if (STORE_ATTRS.has(A)) return attrRaw(u, A, ctx || null) + (u?.store?.[A] || 0);\n 2012        if (!ctx) {\n 2013          if (cacheEpoch !== sim.epoch) { staticCache.clear(); cacheEpoch = sim.epoch; }\n 2014          const ck = u.uid + '|' + A;\n 2015          if (staticCache.has(ck)) return staticCache.get(ck);\n 2016          const v = attrRaw(u, A, null);\n 2017          staticCache.set(ck, v);\n 2018          return v;"},{"f":"battle-sim-core.js","l":1969,"sym":"indexMods","role":"读取/派发点","code":" 1968          else if (s.t === 'CONVERT_ATTRIBUTE' || s.t === 'BUFF_STACK_MODIFY_ATTRIBUTE' ||\n 1969                   s.t === 'BUFF_MODIFY_ATTRIBUTE') {\n 1970            // p1 may be a COMPOSITE id (43 ATTACK / 44 DEFENCE / 5 主属性):\n 1971            // 「每拥有1个减益，防御+5%」must reach PHYSIC_DEFENCE and\n 1972            // SPELL_DEFENCE, otherwise attr() never sees the row.\n 1973            const n = attrName(s.p[1]); for (const A of COMPOSITE[n] || [n]) add(A, inst);\n 1974          }"},{"f":"battle-sim-core.js","l":2103,"sym":"consider","role":"读取/派发点","code":" 2102          // the (negative) maximum. Used to be a flag nothing read.\n 2103          if (s.t === 'BUFF_MODIFY_ATTRIBUTE') {\n 2104            const v = buffTypeCountValue(u, s);\n 2105            pct += v; push(v, inst, s);\n 2106            return;\n 2107          }\n 2108          if (s.t === 'HIT_COUNT_MODIFY_ATTRIBUTE') {"},{"f":"battle-sim-core.js","l":2188,"sym":"record","role":"读取/派发点","code":" 2187            row.note = `${n} 层 × ${s.p[2]}%（上限 ${s.p[3] || '∞'}）`;\n 2188          } else if (s.t === 'BUFF_MODIFY_ATTRIBUTE') {\n 2189            row.pct = buffTypeCountValue(u, s);\n 2190            row.note = `${buffTypeCount(u, s.p[0])} 个对应类型状态 × ${s.p[2]}%（上限 ${s.p[3] || '∞'}）`;\n 2191          } else if (s.t === 'HIT_COUNT_MODIFY_ATTRIBUTE' || s.t === 'DISTANCE_MODIFY_ATTRIBUTE') {\n 2192            row.note = '仅攻击结算时生效'; row.conditional = true;\n 2193          } else {"}],"client":{"speciality_type":119,"params":["大类列表","属性","百分比","最大百分比"],"sparam":""},"impl":"decl"},"id:16912":{"label":"#16912 专属处理","cat":"id","doc":"引擎为该技能/特技/状态编写的专属逻辑或修正说明。","anchors":[{"f":"battle-sim-core.js","l":2100,"sym":"consider","role":"专属处理（引擎按 id 识别）","code":" 2098          // Client speciality_type 「状态属性修正」BUFF_MODIFY_ATTRIBUTE\n 2099          // p = [buff_type 位掩码, 属性, 每个百分比, 最大百分比]: 「每拥有1个减益，\n 2100          // 防御+5%，最大50%」(背叛骑士 #16912, 帕西法尔). Bit (bt-1) of p0 selects\n 2101          // the buff type (4 = bit 2 = 减益). A negative per-buff value caps at\n 2102          // the (negative) maximum. Used to be a flag nothing read.\n 2103          if (s.t === 'BUFF_MODIFY_ATTRIBUTE') {\n 2104            const v = buffTypeCountValue(u, s);"}],"impl":"impl"},"at:56":{"label":"他人回合开始时（active_time 56）","cat":"at","doc":"客户端 active_time 时点：特技只在该时点被派发，fire() 收集持有者全部特技（含状态带来的特技），按 sparam.priority 与声明顺序依次结算。","anchors":[{"f":"battle-sim-core.js","l":9719,"sym":"startTurn","role":"派发 fire(56)","code":" 9718        u.flags.skilled = false; u.flags.instantUsed = new Set(); u.turnStates = new Set();\n 9719        for (const o of units) if (o !== u && o.alive) fire(56, o, {target: u});\n 9720        for (const b of u.buffs.slice()) {\n 9721          if (b.def.end === 1 && Number.isFinite(b.turns)) { b.turns--; b.age = (b.age || 0) + 1; if (b.turns <= 0) removeBuff(u, b, '结束'); }\n 9722        }"}],"impl":"impl"},"sj:priority":{"label":"复合参数 sparam.priority","cat":"sj","doc":"客户端特技的 JSON 复合参数，导出为 spec.sj，由对应处理器读取。","anchors":[{"f":"battle-sim-core.js","l":3803,"sym":"fire","role":"复合参数读取","code":" 3802            u._prioVer = u.ver;\n 3803            u._hasPrio = batch.some(i => i.spec.sj?.priority !== undefined);\n 3804          }\n 3805          const ordered = u._hasPrio ? batch.slice().sort((p, q) =>\n 3806            (Number(q.spec.sj?.priority) || 0) - (Number(p.spec.sj?.priority) || 0)) : batch;\n 3807          for (const inst of ordered) {"},{"f":"battle-sim-core.js","l":3853,"sym":"runSkillSpecs","role":"复合参数读取","code":" 3852        const ordered = (skill.sp || []).slice().sort((a, b) =>\n 3853          ((Number(M?.specs?.[b]?.sj?.priority) || 0) * 100 + (Number(M?.specs?.[b]?.pr) || 0)) -\n 3854          ((Number(M?.specs?.[a]?.sj?.priority) || 0) * 100 + (Number(M?.specs?.[a]?.pr) || 0)));\n 3855        for (const sid of ordered) {\n 3856          const spec = M?.specs?.